function formatCustomDateTime(ts) {
    try {
        // Buat objek Date
        let dateObj;

        // Handle berbagai kemungkinan input timestamp
        if (ts === undefined || ts === null) {
            dateObj = new Date(); // Waktu sekarang jika tidak ada input
        } else if (typeof ts === 'number') {
            // Anggap sebagai Unix timestamp (detik)
            dateObj = new Date(ts * 1000);
        } else if (typeof ts === 'string') {
            // Handle string timestamp
            if (ts.includes('T')) {
                // Format ISO (e.g., "2025-06-05T09:12:39Z")
                dateObj = new Date(ts);
            } else if (/^\d+$/.test(ts)) {
                // String angka (Unix timestamp dalam string)
                dateObj = new Date(parseInt(ts) * 1000);
            } else if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(ts)) {
                // Jika sudah dalam format yang benar, langsung return
                return ts;
            } else {
                // Coba parse format lain
                dateObj = new Date(ts);
            }
        } else {
            // Fallback ke waktu sekarang
            dateObj = new Date();
        }

        // Validasi Date object
        if (isNaN(dateObj.getTime())) {
            throw new Error("Invalid date object");
        }

        // Format sesuai permintaan: "YYYY-MM-DD HH:MM:SS"
        const formatted = dateObj.getFullYear() + '-' +
            String(dateObj.getMonth() + 1).padStart(2, '0') + '-' +
            String(dateObj.getDate()).padStart(2, '0') + ' ' +
            String(dateObj.getHours()).padStart(2, '0') + ':' +
            String(dateObj.getMinutes()).padStart(2, '0') + ':' +
            String(dateObj.getSeconds()).padStart(2, '0');

        // Validasi format output
        if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(formatted)) {
            throw new Error("Formatting failed");
        }

        return formatted;
    } catch (e) {
        node.error("Error in formatCustomDateTime: " + e.toString());
        // Fallback ke waktu sekarang dengan format yang benar
        const now = new Date();
        return now.getFullYear() + '-' +
            String(now.getMonth() + 1).padStart(2, '0') + '-' +
            String(now.getDate()).padStart(2, '0') + ' ' +
            String(now.getHours()).padStart(2, '0') + ':' +
            String(now.getMinutes()).padStart(2, '0') + ':' +
            String(now.getSeconds()).padStart(2, '0');
    }
}

